ROLES = ("egw", "cgw", "rr-inet", "rr-corpnet", "rr-vxlan", "l2-a", "l2-b", "l2-br")


def unify(role, body):
    """The body with the unified zones; the same body when its management block is not the known one."""
    if OLD_FILTER in body:
        return body.replace(OLD_FILTER, {"rr-vxlan": RR_VXLAN_ZONES, "l2-a": L2_ZONES, "l2-b": L2_ZONES}.get(role, "") + NEW_FW)
    if OLD_ZONE in body and NEW_FW not in body:
        return body.replace(LOCAL, "").replace(OLD_ZONE, NEW_FW)
    return body


def forward(apps, schema_editor):
    ConfigTemplate = apps.get_model("inventory", "ConfigTemplate")
    for t in ConfigTemplate.objects.filter(role__in=ROLES):
        new = unify(t.role, t.body)
        if new != t.body:
            t.body = new
            t.save(update_fields=["body"])
        elif NEW_FW not in t.body:
            print(f"  inventory 0061: {t.role} not changed (its management block was edited by hand)")


class Migration(migrations.Migration):
    dependencies = [("inventory", "0060_zone_mgmt_vrf")]
    operations = [migrations.RunPython(forward, migrations.RunPython.noop)]
